import sys
from collections import deque
from typing import List

def solve() -> None:
    n = int(sys.stdin.readline().strip())
    s = sys.stdin.readline().strip()

    q: List[int] = [0]
    for i in range(n):
        if s[i] == 'L':
            q.append(i + 1)
        elif s[i] == 'R':
            q.append(i + 2)

    if len(q) == n:
        print(0)
        return

    q.append(n + 1)
    q.append(-1)
    visited: List[bool] = [False] * n
    visited[0] = True
    visited[-1] = True
    q.append(0)
    while q:
        i = q.popleft()
        if i > 1 and s[i - 2] == 'L':
            if visited[i - 2]:
                q.append(i - 2)
                q.append(i - 1)
                visited[i - 2] = False
                visited[i - 1] = False
        elif i < n - 2 and s[i + 2] == 'R':
            if visited[i + 2]:
                q.append(i + 2)
                q.append(i + 1)
                visited[i + 2] = False
                visited[i + 1] = False

    for i in range(n):
        if not visited[i]:
            print(i + 1, end=' ')
            return

    print(-1)

