        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    def gcd(a, b):
        while b!= 0:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def get_factorial(n):
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    def get_divisors(n):
        result = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                result.append(i)
                if i!= n // i:
                    result.append(n // i)
        return result

    def get_divisors(n):
        result = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                result.add(i)
                result.add(n // i)
        return result

    def get_divisors_set(n):
        return get_divisors(n)

    def get_prime_factors(n):
        result = set()
        for i in range(2, int(n**0.5) + 1):
            while n % i == 0:
                result.add(i)
                n //= i
        if n > 1:
            result.add(n)
        return result

