def solve():
    n = int(input())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    def count_ones(a):
        return sum(1 for x in a if x == 1)

    def count_zeros(a):
        return sum(1 for x in a if x == 0)

    def min_operations(a, b):
        ones_a = count_ones(a)
        ones_b = count_ones(b)
        zeros_a = count_zeros(a)
        zeros_b = count_zeros(b)

        if ones_a == ones_b:
            return 0

        if zeros_a == zeros_b:
            return min(ones_a, ones_b)

        return min(
            ones_a + count_ones(b) - ones_a,
            ones_b + count_zeros(a) - ones_b
        )

    print(min_operations(a, b))

